package service

import (
	"fmt"
	"sync"

	"github.com/google/uuid"
)

// User represents a user in the system
type User struct {
	ID    string `json:"id"`
	Name  string `json:"name"`
	Email string `json:"email"`
}

// UserService handles user-related business logic
type UserService struct {
	users map[string]User
	mutex sync.RWMutex
}

// NewUserService creates a new UserService
func NewUserService() *UserService {
	return &UserService{
		users: make(map[string]User),
	}
}

// CreateUser creates a new user and adds it to the system
func (s *UserService) CreateUser(u User) (User, error) {
	s.mutex.Lock()
	defer s.mutex.Unlock()

	u.ID = uuid.New().String()
	s.users[u.ID] = u
	return u, nil
}

// GetUsers returns all users
func (s *UserService) GetUsers() []User {
	s.mutex.RLock()
	defer s.mutex.RUnlock()

	var list []User
	for _, u := range s.users {
		list = append(list, u)
	}
	return list
}

// GetUserByID returns a user by ID
func (s *UserService) GetUserByID(id string) (User, bool) {
	s.mutex.RLock()
	defer s.mutex.RUnlock()

	u, ok := s.users[id]
	return u, ok
}

package api

import (
	"encoding/json"
	"net/http"
	"strings"

	"rep-4/internal/service"
)

// UserHandlers holds the dependencies for user HTTP handlers
type UserHandlers struct {
	UserService *service.UserService
}

// NewUserHandlers creates a new UserHandlers instance
func NewUserHandlers(us *service.UserService) *UserHandlers {
	return &UserHandlers{UserService: us}
}

// HandleUsers manages requests for /users endpoint
func (uh *UserHandlers) HandleUsers(w http.ResponseWriter, r *http.Request) {
	switch r.Method {
	case http.MethodGet:
		uh.GetUsers(w, r)
	case http.MethodPost:
		uh.CreateUser(w, r)
	default:
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
	}
}

// HandleUserByID manages requests for /users/{id} endpoint
func (uh *UserHandlers) HandleUserByID(w http.ResponseWriter, r *http.Request) {
	id := strings.TrimPrefix(r.URL.Path, "/users/")

	switch r.Method {
	case http.MethodGet:
		uh.GetUserByID(w, r, id)
	default:
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
	}
}

// GetUsers handles GET /users
func (uh *UserHandlers) GetUsers(w http.ResponseWriter, r *http.Request) {
	users := uh.UserService.GetUsers()
	json.NewEncoder(w).Encode(users)
}

// CreateUser handles POST /users
func (uh *UserHandlers) CreateUser(w http.ResponseWriter, r *http.Request) {
	var u service.User
	if err := json.NewDecoder(r.Body).Decode(&u); err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	createdUser, err := uh.UserService.CreateUser(u)
	if err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}

	w.WriteHeader(http.StatusCreated)
	json.NewEncoder(w).Encode(createdUser)
}

// GetUserByID handles GET /users/{id}
func (uh *UserHandlers) GetUserByID(w http.ResponseWriter, r *http.Request, id string) {
	u, ok := uh.UserService.GetUserByID(id)
	if !ok {
		http.NotFound(w, r)
		return
	}
	json.NewEncoder(w).Encode(u)
}

package main

import (
	"log"
	"net/http"

	"rep-4/internal/api"
	"rep-4/internal/service"
)

func main() {
	// Initialize service
	userService := service.NewUserService()

	// Initialize handlers with the service
	userHandlers := api.NewUserHandlers(userService)

	// Register HTTP routes
	http.HandleFunc("/users", userHandlers.HandleUsers)
	http.HandleFunc("/users/", userHandlers.HandleUserByID)

	log.Println("Server starting on :8080...")
	if err := http.ListenAndServe(":8080", nil); err != nil {
		log.Fatal(err)
	}
}

package main

import (
	"bytes"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"testing"

	"rep-4/internal/api"
	"rep-4/internal/service"
)

func TestUserAPI(t *testing.T) {
	// Initialize service and handlers
	userService := service.NewUserService()
	userHandlers := api.NewUserHandlers(userService)

	// Create a new HTTP test server
	rr := httptest.NewRecorder()
	req, _ := http.NewRequest(http.MethodGet, "/users", nil)

	// Test GET /users (empty initially)
	userHandlers.HandleUsers(rr, req)
	if rr.Code != http.StatusOK {
		t.Errorf("Expected status %d, got %d", http.StatusOK, rr.Code)
	}

	var users []service.User
	json.NewDecoder(rr.Body).Decode(&users)
	if len(users) != 0 {
		t.Errorf("Expected 0 users, got %d", len(users))
	}

	// Test POST /users
	newUser := service.User{Name: "Alice", Email: "alice@example.com"}
	jsonBody, _ := json.Marshal(newUser)
	req, _ = http.NewRequest(http.MethodPost, "/users", bytes.NewBuffer(jsonBody))
	rr = httptest.NewRecorder()
	userHandlers.HandleUsers(rr, req)

	if rr.Code != http.StatusCreated {
		t.Errorf("Expected status %d, got %d", http.StatusCreated, rr.Code)
	}

	var createdUser service.User
	json.NewDecoder(rr.Body).Decode(&createdUser)
	if createdUser.Name != newUser.Name || createdUser.Email != newUser.Email || createdUser.ID == "" {
		t.Errorf("Created user mismatch: %+v", createdUser)
	}

	// Test GET /users again (with one user)
	rr = httptest.NewRecorder()
	req, _ = http.NewRequest(http.MethodGet, "/users", nil)
	userHandlers.HandleUsers(rr, req)

	if rr.Code != http.StatusOK {
		t.Errorf("Expected status %d, got %d", http.StatusOK, rr.Code)
	}

	users = []service.User{}
	json.NewDecoder(rr.Body).Decode(&users)
	if len(users) != 1 {
		t.Errorf("Expected 1 user, got %d", len(users))
	}

	// Test GET /users/{id}
	rr = httptest.NewRecorder()
	req, _ = http.NewRequest(http.MethodGet, "/users/"+createdUser.ID, nil)
	userHandlers.HandleUserByID(rr, req)

	if rr.Code != http.StatusOK {
		t.Errorf("Expected status %d, got %d", http.StatusOK, rr.Code)
	}

	var fetchedUser service.User
	json.NewDecoder(rr.Body).Decode(&fetchedUser)
	if fetchedUser.ID != createdUser.ID || fetchedUser.Name != createdUser.Name {
		t.Errorf("Fetched user mismatch: %+v", fetchedUser)
	}

	// Test GET /users/{non-existent-id}
	rr = httptest.NewRecorder()
	req, _ = http.NewRequest(http.MethodGet, "/users/non-existent", nil)
	userHandlers.HandleUserByID(rr, req)

	if rr.Code != http.StatusNotFound {
		t.Errorf("Expected status %d, got %d", http.StatusNotFound, rr.Code)
	}
}
